#!/bin/sh
# Mirror test: replicates the extension's EXACT browser flow — same warm
# profile (/tmp/google_search_profile), same launch flags, same stealth
# patches, same timezone handling — and prints title / final url / h3
# count / captcha presence. Zero dollar-signs in the payload (paste-safe).
pkill Xvfb; pkill -f google-chrome; sleep 0.5; rm -f /tmp/.X11-unix/X99 /tmp/.X99-lock; node -e "const {spawn}=require('child_process');const fs=require('fs');async function main(){const {chromium}=require('/root/.pi/agent/git/github.com/ldsp91/pi-google-search/node_modules/playwright');const xvfb=spawn('Xvfb',[':99','-screen','0','1920x1080x24','-nolisten','tcp'],{stdio:'ignore'});await new Promise(r=>setTimeout(r,1500));if(fs.existsSync('/tmp/.X11-unix/X99')===false){console.log('XVFB-DIED');process.exit(1)};console.log('xvfb up');const t0=Date.now();const ctx=await chromium.launchPersistentContext('/tmp/google_search_profile',{headless:false,executablePath:'/usr/bin/google-chrome',timezoneId:'Europe/Berlin',args:['--no-sandbox','--disable-setuid-sandbox','--disable-blink-features=AutomationControlled','--no-first-run','--no-default-browser-check','--disable-dev-shm-usage'],env:{...process.env,DISPLAY:':99',TZ:'Europe/Berlin'},timeout:30000});const page=await ctx.newPage();await page.addInitScript(function(){Object.defineProperty(navigator,'webdriver',{get:function(){return false}});Object.defineProperty(navigator,'plugins',{get:function(){return {0:{name:'Chrome PDF Plugin'},1:{name:'Chrome PDF Viewer'},2:{name:'Native Client'},length:3}}});Object.defineProperty(navigator,'languages',{get:function(){return ['en-US','en']}});window.chrome={runtime:{onMessage:{addListener:function(){},removeListener:function(){}},onConnect:{addListener:function(){},removeListener:function(){}}}};});await page.goto('https://www.google.com/search?q=hello+world&hl=en',{waitUntil:'domcontentloaded',timeout:20000});await page.waitForTimeout(3000);for(const sel of ['fluent-button[aria-label*=\"Accept\"]','button#L2AGLb','div[role=\"dialog\"] button','center > div > button']){const b=page.locator(sel).first();if(await b.isVisible({timeout:1500}).catch(function(){return false})){await b.click().catch(function(){});await page.waitForTimeout(2000);break}}const info=await page.evaluate(function(){const h3s=Array.from(document.querySelectorAll('h3')).map(function(e){return e.textContent.trim()}).filter(Boolean);const cap=document.querySelector('#captcha-form, .g-recaptcha, #recaptcha');return {title:document.title,h3:h3s.length,first:h3s[0]||'',captcha:cap?true:false,url:location.href}});console.log('elapsed:',Date.now()-t0,'ms');console.log('title:',info.title);console.log('final url:',info.url);console.log('h3 count:',info.h3);console.log('first h3:',info.first);console.log('captcha present:',info.captcha);await ctx.close();xvfb.kill();process.exit(0)}main().catch(function(e){console.log('ERROR:',e.message);process.exit(3)});"
